package com.familygrowth.web;import com.familygrowth.application.Stage8Service;import com.familygrowth.domain.Stage3Models;import com.familygrowth.domain.Stage3Models.Actor;import com.familygrowth.domain.Stage8Models.ChildSyncSnapshot;import java.util.UUID;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/families/{familyId}/children/{childId}") class Stage8Controller{private final Stage8Service service;Stage8Controller(Stage8Service service){this.service=service;}@GetMapping("/sync")ApiResponse<ChildSyncSnapshot> sync(@RequestAttribute(Stage3Models.ACTOR_REQUEST_ATTRIBUTE)Actor actor,@PathVariable UUID familyId,@PathVariable UUID childId){return ApiResponse.ok(service.snapshot(actor,familyId,childId));}}
